{
    var shipment = await service.CreateShipmentAsync(request);
    return Results.Created($"/api/shipments/track/{shipment.TrackingNumber}", shipment);
}).RequireAuthorization();

shipmentApi.MapPut("/{id}/status", async (int id, StatusUpdateRequest request, IShipmentService service) =>
{
    var shipment = await service.UpdateShipmentStatusAsync(id, request.Status);
    return Results.Ok(shipment);
}).RequireAuthorization();

