@page "/"
@attribute [AllowAnonymous]
@using Microsoft.AspNetCore.Authorization
@inject NavigationManager Navigation

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="container mt-5">
    <div class="text-center mb-5">
        <h1 class="display-4">📦 ShipmentTracker</h1>
        <p class="lead text-muted">Track your shipments in real-time. Enter your tracking number below to get started.</p>
