@page "/track"
@page "/track/{TrackingNumber?}"
@attribute [AllowAnonymous]
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2>🔍 Track Your Shipment</h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number"
                       @bind="searchNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="Search" disabled="@(isLoading || string.IsNullOrWhiteSpace(searchNumber))">
                    @if (isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Search
                </button>
            </div>
        </div>
    </div>

    @if (errorMessage is not null)
    {
        <div class="alert alert-warning">@errorMessage</div>
    }

    @if (shipment is not null)
    {
        <div class="card">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
                <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
            </div>
            <div class="card-body">
                <div class="row mb-4">
                    <div class="col-md-6">
                        <p><strong>Origin:</strong> @shipment.Origin</p>
                        <p><strong>Destination:</strong> @shipment.Destination</p>
                    </div>
                    <div class="col-md-6">
                        <p><strong>Created:</strong> @shipment.CreatedAt.ToString("MMM dd, yyyy")</p>
                        @if (shipment.EstimatedDelivery.HasValue)
                        {
                            <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</p>
                        }
                    </div>
                </div>

                @if (shipment.Notes is not null)
                {
                    <p><strong>Notes:</strong> @shipment.Notes</p>
                }

                <h6 class="mt-3">Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @(GetProgressPercent(shipment.Status))%"
                         aria-valuenow="@GetProgressPercent(shipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @shipment.Status
                    </div>
                </div>
                <div class="d-flex justify-content-between mt-1 small text-muted">
                    <span>Pending</span>
                    <span>Picked Up</span>
                    <span>In Transit</span>
                    <span>Out for Delivery</span>
                    <span>Delivered</span>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public string? TrackingNumber { get; set; }

    private string? searchNumber;
    private ShipmentDto? shipment;
    private string? errorMessage;
    private bool isLoading;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchNumber = TrackingNumber;
            await Search();
        }
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(searchNumber)) return;

        isLoading = true;
        errorMessage = null;
        shipment = null;

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchNumber.Trim());
            if (shipment is null)
            {
                errorMessage = $"No shipment found with tracking number '{searchNumber.Trim()}'.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error searching for shipment: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            _ = Search();
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };

    private static int GetProgressPercent(string status) => status switch
    {
        "Pending" => 10,
        "PickedUp" => 30,
        "InTransit" => 55,
        "OutForDelivery" => 80,
        "Delivered" => 100,
        "Cancelled" => 100,
        _ => 0
    };
}

@page "/shipments"
@attribute [Authorize]
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Shipments Dashboard</PageTitle>

<div class="container mt-4">
    <div class="d-flex justify-content-between align-items-center mb-3">
        <h2>📋 Shipments Dashboard</h2>
        <a href="/shipments/create" class="btn btn-success">+ New Shipment</a>
    </div>

    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by tracking number or destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    @if (isLoading)
    {
        <div class="text-center my-5">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (errorMessage is not null)
    {
        <div class="alert alert-danger">@errorMessage</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Created</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td><a href="/track/@s.TrackingNumber">@s.TrackingNumber</a></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@s.CreatedAt.ToString("MMM dd, yyyy")</td>
                            <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                            <td>
                                <div class="dropdown">
                                    <button class="btn btn-sm btn-outline-secondary dropdown-toggle" type="button"
                                            data-bs-toggle="dropdown" aria-expanded="false">
                                        Change Status
                                    </button>
                                    <ul class="dropdown-menu">
                                        @foreach (var status in Statuses)
                                        {
                                            var st = status;
                                            <li>
                                                <button class="dropdown-item @(s.Status == st ? "active" : "")"
                                                        @onclick="() => UpdateStatus(s.Id, st)">
                                                    @st
                                                </button>
                                            </li>
                                        }
                                    </ul>
                                </div>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        @if (!FilteredShipments.Any())
        {
            <div class="text-center text-muted my-3">No shipments match your filter.</div>
        }
    }
</div>

@code {
    private List<ShipmentDto> shipments = [];
    private string? filterText;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = ["Pending", "PickedUp", "InTransit", "OutForDelivery", "Delivered", "Cancelled"];

    private IEnumerable<ShipmentDto> FilteredShipments =>
        string.IsNullOrWhiteSpace(filterText)
            ? shipments
            : shipments.Where(s =>
                s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task UpdateStatus(int id, string status)
    {
        try
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, status);
            var index = shipments.FindIndex(s => s.Id == id);
            if (index >= 0) shipments[index] = updated;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to update status: {ex.Message}";
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/shipments/create"
@attribute [Authorize]
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Create Shipment</PageTitle>

<div class="container mt-4">
    <h2>📦 Create New Shipment</h2>

    @if (errorMessage is not null)
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    <div class="card mt-3">
        <div class="card-body">
            <EditForm Model="request" OnValidSubmit="HandleSubmit" FormName="CreateShipmentForm">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger" />

                <div class="mb-3">
                    <label class="form-label">Origin</label>
                    <InputText class="form-control" @bind-Value="request.Origin" placeholder="e.g. New York, USA" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Destination</label>
                    <InputText class="form-control" @bind-Value="request.Destination" placeholder="e.g. London, UK" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Customer Email</label>
                    <InputText class="form-control" type="email" @bind-Value="request.CustomerEmail" placeholder="customer@example.com" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Estimated Delivery</label>
                    <InputDate class="form-control" @bind-Value="request.EstimatedDelivery" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Notes</label>
                    <InputTextArea class="form-control" @bind-Value="request.Notes" rows="3" placeholder="Optional notes..." />
                </div>

                <div class="d-flex gap-2">
                    <button type="submit" class="btn btn-primary" disabled="@isSubmitting">
                        @if (isSubmitting) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Create Shipment
                    </button>
                    <a href="/shipments" class="btn btn-outline-secondary">Cancel</a>
                </div>
            </EditForm>
        </div>
    </div>
</div>

@code {
    private CreateShipmentRequest request = new();
    private bool isSubmitting;
    private string? errorMessage;

    private async Task HandleSubmit()
    {
