@page "/shipments"
@attribute [Authorize]
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Shipments Dashboard</PageTitle>

<div class="container mt-4">
    <div class="d-flex justify-content-between align-items-center mb-3">
        <h2>📋 Shipments Dashboard</h2>
        <a href="/shipments/create" class="btn btn-success">+ New Shipment</a>
    </div>

    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by tracking number or destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    @if (isLoading)
    {
        <div class="text-center my-5">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (errorMessage is not null)
    {
        <div class="alert alert-danger">@errorMessage</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Created</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td><a href="/track/@s.TrackingNumber">@s.TrackingNumber</a></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@s.CreatedAt.ToString("MMM dd, yyyy")</td>
                            <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                            <td>
                                <div class="dropdown">
                                    <button class="btn btn-sm btn-outline-secondary dropdown-toggle" type="button"
                                            data-bs-toggle="dropdown" aria-expanded="false">
                                        Change Status
                                    </button>
                                    <ul class="dropdown-menu">
                                        @foreach (var status in Statuses)
                                        {
                                            var st = status;
                                            <li>
                                                <button class="dropdown-item @(s.Status == st ? "active" : "")"
                                                        @onclick="() => UpdateStatus(s.Id, st)">
                                                    @st
                                                </button>
                                            </li>
                                        }
                                    </ul>
                                </div>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        @if (!FilteredShipments.Any())
        {
            <div class="text-center text-muted my-3">No shipments match your filter.</div>
        }
    }
</div>

@code {
    private List<ShipmentDto> shipments = [];
    private string? filterText;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = ["Pending", "PickedUp", "InTransit", "OutForDelivery", "Delivered", "Cancelled"];

    private IEnumerable<ShipmentDto> FilteredShipments =>
        string.IsNullOrWhiteSpace(filterText)
            ? shipments
            : shipments.Where(s =>
                s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task UpdateStatus(int id, string status)
    {
        try
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, status);
            var index = shipments.FindIndex(s => s.Id == id);
            if (index >= 0) shipments[index] = updated;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to update status: {ex.Message}";
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

